@@ -125,7 +124,6 @@ static const struct tzinfo tzone[] = {
   { "G", -7 * 60 },            /* Golf */
   { "H", -8 * 60 },            /* Hotel */
   { "I", -9 * 60 },            /* India */
-  { "", -1 },          /* not a timezone */
   { "K", -10 * 60 },           /* Kilo */
   { "L", -11 * 60 },           /* Lima */
   { "M", -12 * 60 },           /* Mike */
@@ -337,7 +335,16 @@ UNITTEST int checktz(const char *check, size_t len)
     /* short-cut single letter names */
     if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
       return -1; /* no such tz */
-    return tzone[check[0] - 'A'].offset * 60;
+    if(check[0] == 'A')
+      return -1 * 60 * 60;
+    {
+      size_t index = (size_t)(check[0] - 'A');
+      if(index > 9)
+        index -= 2;
+      else if(index > 0)
+        index--;
+      return tzone[index].offset * 60;
+    }
   }
   else if(len == 2) {
